const trigger = $('Webhook (dispara desde apps/conteo)').first().json.body;
const fotoBase64 = $json.fotoBase64;

const prompt = `Analizás la fotografía de la caja de un medicamento.
Devolvé ÚNICAMENTE un objeto JSON válido. Sin markdown, sin backticks,
sin explicación, sin texto antes ni después.

Estructura exacta:
{"reconocido":true,"nombre":"","laboratorio":"","concentracion":"","contenido":0,"unidad":"","confianza":0.0}

Reglas:
- nombre: nombre comercial tal como figura en la caja, sin el laboratorio.
- laboratorio: fabricante impreso en la caja.
- concentracion: ej "400 mg", "500 mg/5 ml". Vacío si no está visible.
- contenido: solo el número. "Caja x 20 comprimidos" → 20. "Frasco 120 ml" → 120.
- unidad: uno de comprimidos|capsulas|ml|g|unidades|sobres|ampollas.
- confianza: 0.0 a 1.0 según qué tan legible está la caja.
- NO inventes datos que no estén visibles. Campo ilegible → "" o 0, y bajá la confianza.
- Si no podés identificar el medicamento, devolvé:
  {"reconocido":false,"nombre":"","laboratorio":"","concentracion":"","contenido":0,"unidad":"","confianza":0.0}`;

return {
  json: {
    desconocido_id: trigger.desconocido_id,
    callback_url: trigger.callback_url,
    callback_secret: trigger.callback_secret,
    geminiBody: {
      contents: [
        {
          parts: [
            { text: prompt },
            { inline_data: { mime_type: 'image/jpeg', data: fotoBase64 } }
          ]
        }
      ],
      generationConfig: {
        response_mime_type: 'application/json'
      }
    }
  }
};

const entrada = $input.first().json;
const desconocidoId = $('Armar prompt Gemini (sección 5)').first().json.desconocido_id;
const callbackUrl = $('Armar prompt Gemini (sección 5)').first().json.callback_url;
const callbackSecret = $('Armar prompt Gemini (sección 5)').first().json.callback_secret;

function vacio() {
  return { reconocido: false, nombre: '', laboratorio: '', concentracion: '', contenido: 0, unidad: '', confianza: 0.0 };
}

let resultado;
try {
  // Parseo tolerante: por las dudas Gemini mande el JSON envuelto en
  // ```json ... ``` a pesar de response_mime_type, se lo saca antes de parsear.
  const texto = entrada?.candidates?.[0]?.content?.parts?.[0]?.text ?? '';
  const limpio = texto.replace(/^```json\s*/i, '').replace(/```\s*$/i, '').trim();
  resultado = JSON.parse(limpio);
  if (typeof resultado.reconocido !== 'boolean') resultado = vacio();
} catch (e) {
  resultado = vacio();
}

return {
  json: {
    desconocido_id: desconocidoId,
    callback_url: callbackUrl,
    callback_secret: callbackSecret,
    ...resultado
  }
};
